  70% { transform: scale(1.08); opacity: .08; }
  100% { transform: scale(1.08); opacity: 0; }
}

.active-node::after {
  animation: pulse-ring 1.8s ease-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .active-node::after { animation: none; }
}

